class Solution:
    def minPatches(self, nums: list[int], n: int) -> int:
        reachable = {0}
        patches = i = 0
        nums = list(nums)
        while True:
            miss = 1
            while miss <= n and miss in reachable:
                miss += 1
            if miss > n:
                return patches
            if i < len(nums) and nums[i] <= miss:
                x = nums[i]
                i += 1
            else:
                x = miss
                patches += 1
            for s in list(reachable):
                if s + x <= n:
                    reachable.add(s + x)

