class Solution:
    def minPatches(self, nums, n):
        arr = list(nums)
        patches = i = 0
        miss = 1
        while miss <= n:
            if i < len(arr) and arr[i] <= miss:
                miss += arr[i]
                i += 1
            else:
                arr.insert(i, miss)
                patches += 1
        return patches

